def histogram(test):
    # Split the string into individual letters
    letters = test.split()

    # Initialize a dictionary to count occurrences of each letter
    count = {}

    # Iterate over each letter and update its count
    for letter in letters:
        if letter in count:
            count[letter] += 1
        else:
            count[letter] = 1

    # Find the maximum count
    max_count = max(count.values())

    # Create a dictionary with letters that have the maximum count
    result = {letter: count[letter] for letter in count if count[letter] == max_count}

    # Return the result dictionary
    return result

