def tri(n):
    # Initialize the list with the first three numbers of the Tribonacci sequence
    tribonacci = [1, 3, 2]

    # If n is less than or equal to 2, return the first n + 1 numbers
    if n <= 2:
        return tribonacci[:n + 1]

    # Calculate the rest of the numbers in the sequence
    for i in range(3, n + 1):
        if i % 2 == 0:
            tribonacci.append(1 + i / 2)
        else:
            tribonacci.append(tribonacci[i - 1] + tribonacci[i - 2] + tribonacci[i + 1])

    # Return the list of the first n + 1 numbers of the Tribonacci sequence
    return tribonacci

